'use strict';
const labels={buff:'강화',debuff:'약화',cc:'제어',mark:'표식',etc:'조건·기타'};
const order=['buff','debuff','cc','mark','etc'];
const state={failed:new Set()};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const q=document.querySelector('#query').value.trim().toLowerCase(),entries=window.DosulEffectIcons.names().map(name=>({name,...window.DosulEffectIcons.entry(name)})).filter(x=>!q||`${x.name} ${x.sourceName} ${x.src}`.toLowerCase().includes(q));document.querySelector('#groups').innerHTML=order.map(kind=>{const rows=entries.filter(x=>(x.kind||'etc')===kind);if(!rows.length)return'';return `<section class="effect-group"><h2>${labels[kind]} <small>${rows.length}</small></h2><div class="icon-grid">${rows.map(x=>`<article class="effect-card ${state.failed.has(x.name)?'error':''}" data-name="${esc(x.name)}"><span class="icon-frame"><img src="${esc(x.src)}" alt="${esc(x.name)}" width="40" height="40"></span><span><b>${esc(x.name)}</b><small>원본: ${esc(x.sourceName)}</small><small class="path">${esc(x.src.split('/').pop())}</small></span></article>`).join('')}</div></section>`;}).join('')||'<p class="empty">검색 결과 없음</p>';document.querySelectorAll('.effect-card img').forEach(img=>img.addEventListener('error',()=>{state.failed.add(img.closest('.effect-card').dataset.name);img.closest('.effect-card').classList.add('error');document.querySelector('#errors').textContent=state.failed.size;}));}
const names=window.DosulEffectIcons.names(),unique=new Set(names.map(name=>window.DosulEffectIcons.src(name)));
document.querySelector('#total').textContent=names.length;document.querySelector('#assets').textContent=unique.size;document.querySelector('#errors').textContent='0';document.querySelector('#query').addEventListener('input',render);render();
